@app.route("/logo.jpg")
@app.route("/logo.jpeg")
def logo_file():
    for f in ["logo.jpg","logo.jpeg","logo.png"]:
        if os.path.exists(f):
            return send_file(f, mimetype="image/jpeg")
    return "logo missing", 404
@app.route("/barcode.png")
def barcode():
    from flask import Response
    import urllib.request
    url = "https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=https://alqarawi.onrender.com"
    try:
        data = urllib.request.urlopen(url).read()
        return Response(data, mimetype="image/png")
    except:
        return "خطأ", 500
