    days="".join([f'<option>{d}</option>' for d in ["السبت - الخميس","السبت - الجمعة","الأحد - الخميس","كل يوم","الجمعة"]])
    times="".join([f'<option>{t}</option>' for t in ["8ص","9ص","10ص","12م","4م","5م","10م","11م","بعد أذان الظهر","بعد أذان العصر بنصف ساعة","بعد أذان العصر","بعد أذان المغرب","بعد أذان العشاء","بعد أذان العشاء بنصف ساعة"]])
    cities=["الرياض","مكة","المدينة","جدة","الدمام","بريدة","أبها","خميس مشيط","تبوك","حائل","جازان","نجران","الباحة","عرعر","سكاكا","ينبع","الطائف","الخبر","الأحساء","حفر الباطن","القطيف","عنيزة","الرس","المجمعة","الخرج","وادي الدواسر","بيشة","القنفذة"]
    city_opts="".join([f'<option>{c}</option>' for c in cities])
    products_json=json.dumps(db["products"], ensure_ascii=False); branches_json=json.dumps(db["branches"], ensure_ascii=False); rev_filter="".join([f'<option>{b["name"]}</option>' for b in db["branches"] if b["name"].strip()])
    rev_items="".join([f'<div class="rev-item" data-branch="{r["branch"]}" style="border:1px solid #ddd;padding:10px;margin:6px 0;background:#fff"><b>{r["name"]} - {r["branch"]}</b><p>{r["text"]}</p><p>⭐ {r["stars"]}</p>' + (f'<img src="{r["img"]}" style="width:120px">' if r.get("img") else "") + '</div>' for r in db.get("reviews",[])])
    rev = f'<select id="revBranch" onchange="filterRev()" style="width:100%;padding:10px;margin:6px 0"><option value="الكل">كل الفروع</option>{rev_filter}</select><div id="revList" style="height:400px;overflow-y:auto;border:1px solid #ddd;padding:10px;background:#f9f9f9">{rev_items}</div><script>function filterRev(){{let v=document.getElementById("revBranch").value;document.querySelectorAll(".rev-item").forEach(el=>{{el.style.display=(v==="الكل"||el.dataset.branch===v)?"block":"none"}});}}</script>'
    return f'<div style="padding:20px;font-family:Arial;max-width:900px;margin:auto"><script>let branchesData = JSON.parse(document.getElementById("branchesData").textContent);</script><script id="branchesData" type="application/json">{branches_json}</script><script id="productsData" type="application/json">{products_json}</script><script>let productsData = JSON.parse(document.getElementById("productsData").textContent);</script><h2>الإدارة - {session["user"]}</h2><h3>➕ إضافة فرع جديد</h3><form method="post"><input name="bname" placeholder="اسم الفرع" style="width:100%;padding:10px;margin:4px 0"><select name="bcity" style="width:100%;padding:10px;margin:4px 0"><option value="">اختار المدينة</option>{city_opts}</select><input name="bcity_manual" placeholder="أو اكتب مدينة جديدة مش موجودة - مثال: أبها" style="width:100%;padding:10px;margin:4px 0"><input name="bphone" placeholder="واتساب" style="width:100%;padding:10px;margin:4px 0"><input name="bloc" placeholder="رابط الموقع" style="width:100%;padding:10px;margin:4px 0"><input name="custom1" placeholder="أو اكتب نص الدوام بنفسك - مثال: بعد أذان العصر بنصف ساعة" style="width:100%;padding:10px;margin:4px 0"><p>دوام 1: <select name="h1d">{days}</select> من <select name="h1f">{times}</select> إلى <select name="h1t">{times}</select></p><input name="custom2" placeholder="أو اكتب نص الدوام بنفسك - مثال: بعد أذان العشاء" style="width:100%;padding:10px;margin:4px 0"><p>دوام 2: <select name="h2d">{days}</select> من <select name="h2f">{times}</select> إلى <select name="h2t">{times}</select></p><label><input type="checkbox" name="friday_open" checked> بيداوم الجمعة</label><p>دوام الجمعة: من <select name="fri_from"><option>بعد أذان العصر بنصف ساعة</option><option>بعد أذان الظهر</option><option>بعد أذان العصر</option></select> إلى <select name="fri_to"><option>أذان العشاء</option><option>بعد أذان العشاء</option><option>10م</option></select></p><button name="add_branch" style="padding:10px 20px;background:#22c55e;color:#fff;border:0;border-radius:8px">إضافة فرع</button></form><h3>تعديل فرع - قايمة منسدلة - اختار الفرع يظهر بياناته</h3><div id="branchInfo" style="background:#f9f9f9;padding:10px;border:1px solid #ddd;margin:6px 0">اختار الفرع من القايمة - هتظهر بياناته هنا</div><form method="post"><select name="branch_idx" id="branchSelect" onchange="showBranchData()">{opts}</select><input name="name" placeholder="اسم الفرع الجديد"><select name="bcity_edit" style="width:100%;padding:10px;margin:4px 0"><option value="">اختار المدينة - سيبها فاضية لو مش هتغير</option>{city_opts}</select><input name="bcity_manual_edit" placeholder="أو اكتب مدينة يدوي لو مش موجودة في القايمة" style="width:100%;padding:10px;margin:4px 0;color:#000;background:#fff;border:2px solid #22c55e" style="width:100%;padding:10px;margin:4px 0"><input name="bphone_edit" placeholder="رقم الجوال - واتساب الفرع" style="width:100%;padding:10px;margin:4px 0"><input name="bloc_edit" placeholder="رابط الموقع - خرائط جوجل" style="width:100%;padding:10px;margin:4px 0"><p>دوام 1: <select name="h1d">{days}</select> من <select name="h1f">{times}</select> إلى <select name="h1t">{times}</select></p><p>دوام 2: <select name="h2d">{days}</select> من <select name="h2f">{times}</select> إلى <select name="h2t">{times}</select></p><label><input type="checkbox" name="friday_open" checked> بيداوم الجمعة</label><p>دوام الجمعة: من <select name="fri_from"><option>بعد أذان العصر بنصف ساعة</option><option>بعد أذان الظهر</option><option>بعد أذان العصر</option></select> إلى <select name="fri_to"><option>أذان العشاء</option><option>بعد أذان العشاء</option><option>10م</option></select></p><button name="edit_branch" style="padding:10px 20px;background:#e11d48;color:#fff;border:0;border-radius:8px">حفظ الفرع</button></form><div id="productInfo" style="background:#f9f9f9;padding:10px;border:1px solid #ddd;margin:6px 0">اختار المنتج من القايمة - هتظهر بياناته هنا</div><h3>تعديل منتج - الصورة تنزيل مش رابط</h3><form method="post" enctype="multipart/form-data"><select name="prod_idx" id="prodSelect" onchange="showProdData()">{popts}</select><input name="pname" placeholder="اسم المنتج"><input name="price" placeholder="السعر"><label>نزل الصورة من جوالك: <input type="file" name="pimg" accept="image/*"></label><input name="imgurl" placeholder="أو حط رابط صورة"><button style="padding:10px 20px;background:#e11d48;color:#fff;border:0;border-radius:8px">حفظ المنتج</button></form><h3>إضافة مستخدم وصلاحيات</h3><form method="post"><input name="new_user" placeholder="اسم الجديد"><input name="new_pass" placeholder="باسورد"><label><input type="checkbox" name="perms" value="branches"> تعديل الفروع</label><label><input type="checkbox" name="perms" value="ads"> تعديل الإعلانات</label><label><input type="checkbox" name="perms" value="hours"> تعديل الدوام</label><label><input type="checkbox" name="perms" value="add"> إضافة فرع / إعلان</label><label><input type="checkbox" name="perms" value="users"> إدارة المستخدمين</label><button>إضافة</button></form><h3>تعديل مستخدم - قايمة منسدلة</h3><form method="post"><select name="edit_user_idx" style="width:100%;padding:10px;margin:4px 0">{user_opts}</select><input name="edit_user_pass" placeholder="كلمة السر الجديدة - سيبها فاضية لو مش هتغير"><label><input type="checkbox" name="edit_perms" value="branches"> تعديل الفروع</label><label><input type="checkbox" name="edit_perms" value="ads"> تعديل الإعلانات</label><label><input type="checkbox" name="edit_perms" value="hours"> تعديل الدوام</label><label><input type="checkbox" name="edit_perms" value="add"> إضافة فرع / إعلان</label><label><input type="checkbox" name="edit_perms" value="users"> إدارة المستخدمين</label><button>حفظ المستخدم</button></form><h3>حسابي - تغيير كلمة سري</h3><form method="post"><input name="my_pass" placeholder="كلمة السر الجديدة"><button>تغيير</button></form><h3>📩 تقييمات العملاء - للإدارة فقط</h3>{rev}<p>✅ تعديلك هيسمع عند كل الناس فورا</p><a href="/">رجوع للموقع</a></div>' + "<script>function showBranchData(){var s=document.getElementById('branchSelect');var i=s.value;var e=document.getElementById('branchesData');if(!e)return;var b=JSON.parse(e.textContent)[i];if(b){document.getElementById('branchInfo').innerHTML=b.name+' - '+b.city+' - '+b.phone+' - '+b.loc;document.querySelector('input[name=name]').value=b.name;}} function showProdData(){var s=document.getElementById('prodSelect');var i=s.value;var e=document.getElementById('productsData');if(!e)return;var p=JSON.parse(e.textContent)[i];if(p){document.getElementById('productInfo').innerHTML=p.name+' - '+p.model+' - '+p.price;document.querySelector('input[name=pname]').value=p.name;}}</script>"
